
--- ESTA ES LA BASE DE DATOS CON LA QUE SE HARAN LAS PREGUNTAS Y EL PROYECTO

-- ============================================================
-- Base de datos: tienda_online (PostgreSQL)
-- Tienda de tecnologia y hogar en Colombia. 9 tablas, ~5.000 registros.
-- Uso:  createdb tienda_online && psql -d tienda_online -f tienda_online.sql
-- ============================================================
DROP TABLE IF EXISTS envios, pagos, detalle_pedidos, pedidos, productos, empleados, clientes, proveedores, categorias CASCADE;

CREATE TABLE categorias (
  id            SERIAL PRIMARY KEY,
  nombre        VARCHAR(60) NOT NULL UNIQUE,
  descripcion   TEXT
);
CREATE TABLE proveedores (
  id        SERIAL PRIMARY KEY,
  nombre    VARCHAR(100) NOT NULL,
  nit       VARCHAR(15) NOT NULL UNIQUE,
  ciudad    VARCHAR(60) NOT NULL,
  telefono  VARCHAR(20),
  email     VARCHAR(100),
  activo    BOOLEAN NOT NULL DEFAULT TRUE
);
CREATE TABLE productos (
  id              SERIAL PRIMARY KEY,
  sku             VARCHAR(20) NOT NULL UNIQUE,
  nombre          VARCHAR(120) NOT NULL,
  categoria_id    INT NOT NULL REFERENCES categorias(id),
  proveedor_id    INT NOT NULL REFERENCES proveedores(id),
  precio_unitario NUMERIC(12,2) NOT NULL CHECK (precio_unitario > 0),
  costo           NUMERIC(12,2) NOT NULL CHECK (costo > 0),
  stock           INT NOT NULL DEFAULT 0 CHECK (stock >= 0),
  activo          BOOLEAN NOT NULL DEFAULT TRUE,
  fecha_creacion  DATE NOT NULL
);
CREATE TABLE clientes (
  id              SERIAL PRIMARY KEY,
  nombre          VARCHAR(60) NOT NULL,
  apellido        VARCHAR(60) NOT NULL,
  email           VARCHAR(100) NOT NULL UNIQUE,
  telefono        VARCHAR(20),
  ciudad          VARCHAR(60) NOT NULL,
  departamento    VARCHAR(60) NOT NULL,
  segmento        VARCHAR(15) NOT NULL CHECK (segmento IN ('Regular','Premium','Corporativo')),
  fecha_registro  DATE NOT NULL
);
CREATE TABLE empleados (
  id            SERIAL PRIMARY KEY,
  nombre        VARCHAR(60) NOT NULL,
  apellido      VARCHAR(60) NOT NULL,
  cargo         VARCHAR(60) NOT NULL,
  area          VARCHAR(40) NOT NULL,
  salario       NUMERIC(12,2) NOT NULL,
  fecha_ingreso DATE NOT NULL,
  jefe_id       INT REFERENCES empleados(id)
);
CREATE TABLE pedidos (
  id            SERIAL PRIMARY KEY,
  cliente_id    INT NOT NULL REFERENCES clientes(id),
  empleado_id   INT REFERENCES empleados(id),
  fecha_pedido  TIMESTAMP NOT NULL,
  estado        VARCHAR(15) NOT NULL CHECK (estado IN ('procesando','enviado','entregado','cancelado','devuelto')),
  canal         VARCHAR(15) NOT NULL CHECK (canal IN ('web','app','tienda','telefono'))
);
CREATE TABLE detalle_pedidos (
  id              SERIAL PRIMARY KEY,
  pedido_id       INT NOT NULL REFERENCES pedidos(id) ON DELETE CASCADE,
  producto_id     INT NOT NULL REFERENCES productos(id),
  cantidad        INT NOT NULL CHECK (cantidad > 0),
  precio_unitario NUMERIC(12,2) NOT NULL,
  descuento_pct   NUMERIC(4,1) NOT NULL DEFAULT 0 CHECK (descuento_pct BETWEEN 0 AND 100)
);
CREATE TABLE pagos (
  id          SERIAL PRIMARY KEY,
  pedido_id   INT NOT NULL REFERENCES pedidos(id) ON DELETE CASCADE,
  metodo      VARCHAR(20) NOT NULL,
  monto       NUMERIC(14,2) NOT NULL,
  fecha_pago  TIMESTAMP,
  estado      VARCHAR(15) NOT NULL CHECK (estado IN ('pendiente','aprobado','rechazado','reembolsado'))
);
CREATE TABLE envios (
  id              SERIAL PRIMARY KEY,
  pedido_id       INT NOT NULL REFERENCES pedidos(id) ON DELETE CASCADE,
  transportadora  VARCHAR(40) NOT NULL,
  guia            VARCHAR(20) NOT NULL,
  fecha_envio     DATE NOT NULL,
  fecha_entrega   DATE,
  estado          VARCHAR(15) NOT NULL CHECK (estado IN ('en_transito','entregado','devuelto'))
);
CREATE INDEX idx_productos_categoria ON productos(categoria_id);
CREATE INDEX idx_pedidos_cliente ON pedidos(cliente_id);
CREATE INDEX idx_pedidos_fecha ON pedidos(fecha_pedido);
CREATE INDEX idx_detalle_pedido ON detalle_pedidos(pedido_id);
CREATE INDEX idx_detalle_producto ON detalle_pedidos(producto_id);
CREATE INDEX idx_pagos_pedido ON pagos(pedido_id);
CREATE INDEX idx_envios_pedido ON envios(pedido_id);

